// Let's find any blocks further out for the parkour map
let blocks = bot.findBlocks({
    matching: block => block && block.name && (block.name.includes('slab') || block.name.includes('stair') || block.name.includes('stone') || block.name.includes('wool') || block.name.includes('concrete') || block.name.includes('terracotta')),
    maxDistance: 30,
    count: 30
});

let p = bot.entity.position;
// Filter out blocks too close or below us in a bad way, and sort by distance
let validBlocks = blocks.filter(b => b.distanceTo(p) > 2);
validBlocks.sort((a, b) => p.distanceTo(a) - p.distanceTo(b));

if (validBlocks.length > 0) {
    let target = validBlocks[0];
    bot.chat(`Moving to parkour block at ${target.x}, ${target.y}, ${target.z}`);
    await skills.goToPosition(bot, target.x, target.y, target.z);
} else {
    bot.chat("Looking for parkour blocks further ahead...");
    // Just move forward a bit in the direction we are facing
    let facing = bot.entity.yaw;
    let targetX = p.x - Math.sin(facing) * 5;
    let targetZ = p.z + Math.cos(facing) * 5;
    await skills.goToPosition(bot, targetX, p.y, targetZ);
}```
